public static int calculateTimeNeeded(int N) {
    if (N <= 1) return 0;
    if (N % 2 == 0) {
        int half = N / 2;
        return half * (half - 1);
    } else {
        int half = (N - 1) / 2;
        return half * half;
    }
}

public static int calculateTimeNeeded(int N) {
    if (N <= 1) {
        return 0;
    }
    if (N % 2 != 0) { // odd
        return N - 1;
    } else if (N % 4 == 0) { // even and divisible by 4
        return N - 2;
    } else { // even but not divisible by 4
        return N;
    }
}

