public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to limit search space
    String shortest = strings.get(0);
    for (String s : strings) {
        if (s != null && s.length() < shortest.length()) {
            shortest = s;
        }
    }
    int maxLen = shortest.length();
    for (int len = maxLen; len >= 1; len--) {
        // For each substring of the shortest string with current length
        for (int start = 0; start <= shortest.length() - len; start++) {
            String sub = shortest.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (s == null) {
                    allMatch = false;
                    break;
                }
                if (!(s.contains(sub) || s.contains(rev))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(java.util.List<String> strings) {
    java.util.Set<String> substrSet = new java.util.HashSet<>();
    // Collect all substrings from all strings
    for (String s : strings) {
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                substrSet.add(s.substring(i, j));
            }
        }
    }
    int maxLen = 0;
    // Search for the longest substring whose reverse also exists
    for (String sub : substrSet) {
        int l = sub.length();
        if (l <= maxLen) {
            continue;
        }
        String rev = new StringBuilder(sub).reverse().toString();
        if (substrSet.contains(rev)) {
            maxLen = l;
        }
    }
    return maxLen;
}

