public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to create a unique key for a coordinate array
    java.util.function.Function<int[], String> key = coord -> java.util.Arrays.toString(coord);

    // Quick check: if start equals end
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Build adjacency map from paths
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 2 * n) {
                continue; // skip malformed path
            }
            int[] a = java.util.Arrays.copyOfRange(p, 0, n);
            int[] b = java.util.Arrays.copyOfRange(p, n, 2 * n);
            String keyA = key.apply(a);
            String keyB = key.apply(b);
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        }
    }

    String startKey = key.apply(start);
    String endKey = key.apply(end);
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Deque<String> queue = new java.util.ArrayDeque<>();

    visited.add(startKey);
    queue.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : adj.getOrDefault(current, java.util.Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

