                if (visited.contains(nb)) continue;
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) return "cannot be travelled";
    if (start == null || end == null || start.length == 0 || end.length == 0) return "cannot be travelled";
    int src = start[0];
    int dst = end[0];
    if (src < 0 || src >= n || dst < 0 || dst >= n) return "cannot be travelled";
    if (src == dst) return "can be travelled";

    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    for (int i = 0; i < paths.length; i++) {
        int[] p = paths[i];
        if (p == null || p.length < 2) continue;
        int a = p[0];
        int b = p[1];
        if (a >= 0 && a < n && b >= 0 && b < n) {
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
    }

    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    queue.add(src);
    visited[src] = true;

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj.get(cur)) {
            if (!visited[nb]) {
                if (nb == dst) return "can be travelled";
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != end.length || paths == null) {
        return "cannot be travelled";
    }
    int dim = start.length;

    // Helper class to create a string key from coordinates
    class KeyMaker {
        int d;
        KeyMaker(int d) { this.d = d; }
        String toKey(int[] coords) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < d; i++) {
                sb.append(coords[i]);
                if (i < d - 1) sb.append(",");
            }
            return sb.toString();
        }
    }
    KeyMaker km = new KeyMaker(dim);
    String startKey = km.toKey(start);
    String endKey = km.toKey(end);

    // Validate coordinate bounds
    for (int v : start) {
        if (v < 0 || v >= n) return "cannot be travelled";
    }
    for (int v : end) {
        if (v < 0 || v >= n) return "cannot be travelled";
    }

    java.util.Map<String, java.util.Set<String>> graph = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 2 * dim) continue;
        int[] a = new int[dim];
        int[] b = new int[dim];
        System.arraycopy(p, 0, a, 0, dim);
        System.arraycopy(p, dim, b, 0, dim);
        String ka = km.toKey(a);
        String kb = km.toKey(b);
        graph.computeIfAbsent(ka, k -> new java.util.HashSet<>()).add(kb);
        graph.computeIfAbsent(kb, k -> new java.util.HashSet<>()).add(ka);
    }

    if (startKey.equals(endKey)) return "can be travelled";

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.Set<String> neighbours = graph.get(cur);
        if (neighbours == null) continue;
        for (String nb : neighbours) {
            if (visited.contains(nb)) continue;
            if (nb.equals(endKey)) return "can be travelled";
            visited.add(nb);
            queue.add(nb);
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length < 2 || end.length < 2) {
        return "cannot be travelled";
    }
    int startKey = start[0] * (n + 1) + start[1];
    int endKey = end[0] * (n + 1) + end[1];
    if (startKey == endKey) {
        return "can be travelled";
    }
    java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length < 4) {
            continue;
        }
        int aKey = p[0] * (n + 1) + p[1];
        int bKey = p[2] * (n + 1) + p[3];
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    visited.add(startKey);
    queue.offer(startKey);
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        java.util.List<Integer> neighbors = adj.getOrDefault(curr, java.util.Collections.emptyList());
        for (int nb : neighbors) {
            if (nb == endKey) {
                return "can be travelled";
            }
            if (visited.add(nb)) {
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

