public static String appx(String word1, String word2) {
    int len1 = word1.length();
    int len2 = word2.length();
    int minLen = Math.min(len1, len2);
    int matches = 0;
    for (int i = 0; i < minLen; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            matches++;
        }
    }
    int numerator = matches * 2;
    int denominator = len1 + len2;
    String result;
    if (numerator == 0) {
        result = "0";
    } else if (numerator == denominator) {
        result = "1";
    } else {
        int a = numerator;
        int b = denominator;
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        int gcd = a;
        numerator /= gcd;
        denominator /= gcd;
        result = numerator + "/" + denominator;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

