public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // for each remainder i, freq[i] must equal freq[k - i]
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) { // special case when k is even and i == k/2
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[k - i]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0 || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int val : arr) {
        int rem = val % k;
        if (rem < 0) {
            rem += k;
        }
        count[rem]++;
    }
    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && count[k / 2] % 2 != 0) {
        return false;
    }
    // For other remainders, counts must match complementary remainder
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // already handled for even k
            continue;
        }
        if (count[r] != count[complement]) {
            return false;
        }
    }
    return true;
}

