    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    boolean[] visited = new boolean[n];
    return dfs(0, adj, visited, hasApple);
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (sb.length() < s.length()) {
        /* Ascending part */
        int lastAsc = -1;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                lastAsc = i;
                break;
            }
        }
        if (lastAsc != -1) {
            for (int i = lastAsc + 1; i < 26; i++) {
                if (freq[i] > 0) {
                    sb.append((char) ('a' + i));
                    freq[i]--;
                    lastAsc = i;
                }
            }
        }
        /* Descending part */
        int lastDesc = -1;
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                lastDesc = i;
                break;
            }
        }
        if (lastDesc != -1) {
            for (int i = lastDesc - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    sb.append((char) ('a' + i));
                    freq[i]--;
                }
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) freq[c - 'a']++;
    int total = s.length();
    StringBuilder sb = new StringBuilder(total);
    while (total > 0) {
        // Ascending part
        int i = 0;
        while (i < 26 && freq[i] == 0) i++;
        if (i == 26) break;
        sb.append((char)(i + 'a'));
        freq[i]--; total--;
        char last = (char)(i + 'a');
        while (true) {
            int j = last - 'a' + 1;
            while (j < 26 && freq[j] == 0) j++;
            if (j == 26) break;
            sb.append((char)(j + 'a'));
            freq[j]--; total--;
            last = (char)(j + 'a');
        }
        // Descending part
        int k = 25;
        while (k >= 0 && freq[k] == 0) k--;
        if (k < 0) break;
        sb.append((char)(k + 'a'));
        freq[k]--; total--;
        last = (char)(k + 'a');
        while (true) {
            int l = last - 'a' - 1;
            while (l >= 0 && freq[l] == 0) l--;
            if (l < 0) break;
            sb.append((char)(l + 'a'));
            freq[l]--; total--;
            last = (char)(l + 'a');
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    int taken = 0;
    while (taken < total) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                if (++taken == total) {
                    return result.toString();
                }
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                if (++taken == total) {
                    return result.toString();
                }
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder res = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Character current = map.firstKey();
        res.append(current);
        Integer cnt = map.get(current);
        if (cnt == 1) {
            map.remove(current);
        } else {
            map.put(current, cnt - 1);
        }
        while (true) {
            Character next = map.higherKey(current);
            if (next == null) break;
            res.append(next);
            cnt = map.get(next);
            if (cnt == 1) {
                map.remove(next);
            } else {
                map.put(next, cnt - 1);
            }
            current = next;
        }
        // Descending phase
        if (map.isEmpty()) break;
        current = map.lastKey();
        res.append(current);
        cnt = map.get(current);
        if (cnt == 1) {
            map.remove(current);
        } else {
            map.put(current, cnt - 1);
        }
        while (true) {
            Character next = map.lowerKey(current);
            if (next == null) break;
            res.append(next);
            cnt = map.get(next);
            if (cnt == 1) {
                map.remove(next);
            } else {
                map.put(next, cnt - 1);
            }
            current = next;
        }
    }
    return res.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        freq[ch - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int v : nums) {
        total += v;
    }

    // For each possible subset size k (1 <= k <= n/2)
    for (int k = 1; k <= n / 2; k++) {
        long totalTimesK = (long) total * k;
        if (totalTimesK % n != 0) {
            continue; // average cannot be equal for this k
        }
        int target = (int) (totalTimesK / n); // target sum for subset of size k

        @SuppressWarnings("unchecked")
        Set<Integer>[] dp = new HashSet[k + 1];
        for (int i = 0; i <= k; i++) {
            dp[i] = new HashSet<>();
        }
        dp[0].add(0);

        for (int num : nums) {
            for (int size = Math.min(k, num == 0 ? 0 : k); size >= 1; size--) {
                // For each sum achievable with size-1 elements, add current number
                for (int s : dp[size - 1]) {
                    dp[size].add(s + num);
                }
            }
        }

        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (!dp[k].isEmpty()) {
                for (int s : dp[k]) {
                    dp[k + 1].add(s + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) dp[i] = new java.util.HashSet<>();
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    int n = nums.length;
    for (int num : nums) sum += num;
    if (n == 0) return false;
    java.util.List<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<Integer>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int i = n - 1; i >= 1; i--) {
            java.util.Set<Integer> prevSet = dp.get(i - 1);
            java.util.Set<Integer> currentSet = dp.get(i);
            for (int prevSum : prevSet) {
                currentSet.add(prevSum + num);
            }
        }
    }
    for (int i = 1; i < n; i++) {
        if ((sum * i) % n != 0) continue;
        int target = (sum * i) / n;
        if (dp.get(i).contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        List<HashSet<Integer>> dp = new ArrayList<>(k + 1);
        for (int i = 0; i <= k; i++) {
            dp.add(new HashSet<>());
        }
        dp.get(0).add(0);
        for (int num : nums) {
            for (int sz = k - 1; sz >= 0; sz--) {
                for (int s : dp.get(sz)) {
                    int newSum = s + num;
                    if (sz + 1 == k && newSum == target) {
                        return true;
                    }
                    dp.get(sz + 1).add(newSum);
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int takeOne = dp[i - 1] + cost[i - 1];
        int takeTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(takeOne, takeTwo);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) return 0;
    int prev = cost[0];
    int curr = cost[1];
    for (int i = 2; i < n; i++) {
        int next = cost[i] + Math.min(prev, curr);
        prev = curr;
        curr = next;
    }
    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int a = cost[0];
    int b = cost[1];
    for (int i = 2; i < n; i++) {
        int c = cost[i] + Math.min(a, b);
        a = b;
        b = c;
    }
    return Math.min(a, b);
}

