public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k; // number of possible binary strings of length k
    if (n - k + 1 < total) return false;
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskBits = total - 1; // bitmask to keep k bits
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    for (int i = k; i < n; i++) {
        // slide window: shift left, add new bit, keep only k bits
        mask = ((mask << 1) | (s.charAt(i) - '0')) & maskBits;
        seen[mask] = true;
    }
    // at this point some codes might also appear in last k... but we covered all windows
    // However, first window already recorded. All windows processed.
    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;

    int val = 0;
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;

    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        seen[val] = true;
    }

    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int required = 1 << k; // 2^k possible binary strings of length k
    int n = s.length();
    if (n < k) return false; // not enough length to contain all codes

    boolean[] seen = new boolean[required];
    int mask = 0;
    int maskLimit = required - 1; // to keep only k bits

    for (int i = 0; i < n; i++) {
        // Shift left, add current bit, and keep only k bits
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        // When we have read at least k characters, record the code
        if (i >= k - 1) {
            seen[mask] = true;
        }
    }

    // Check that all k-bit codes were seen
    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) return false;
    int needed = 1 << k;
    if (s.length() < needed) return false;

    boolean[] seen = new boolean[needed];
    int mask = needed - 1;
    int window = 0;
    int distinct = 0;

    for (int i = 0; i < s.length(); i++) {
        window = ((window << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[window]) {
                seen[window] = true;
                distinct++;
                if (distinct == needed) return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) {
        return true;
    }
    if (k > n) {
        return false;
    }
    java.util.Set<Integer> seen = new java.util.HashSet<>();
    int val = 0;
    // process first window
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen.add(val);
    int mask = (1 << k) - 1; // keep only k bits (valid when k < 31)
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        seen.add(val);
    }
    long total = 1L << k; // number of possible binary strings of length k
    return seen.size() == total;
}

