public int minInsertions(String s) {
    int neededOpen = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // ')'
            if (balance == 0) {
                neededOpen++;
            } else {
                balance--;
            }
        }
    }
    return neededOpen + balance;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // Need an '(' before this ')' to match it
                insertions++;
                // After inserting, we consider this ')' matched, so balance remains 0
            }
        }
    }
    // Add ')' for any remaining unmatched '('
    insertions += balance;
    return insertions;
}

