    int currentMin = 0, minSum = Integer.MAX_VALUE;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        if (currentMax > maxSum) {
            maxSum = currentMax;
        }
        currentMin = Math.min(num, currentMin + num);
        if (currentMin < minSum) {
            minSum = currentMin;
        }
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }
    // Greedy subtraction from the largest Fibonacci number
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

