public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        factors.add(large.get(i));
    }
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    // Combine small list with reversed large list to get ascending order
    java.util.Comparator<Integer> revComp = java.util.Collections.reverseOrder();
    java.util.Collections.sort(large, revComp);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    return large.get(k - 1 - small.size());
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (i != other) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k - 1 < factors.size()) {
        return factors.get(k - 1);
    }
    return -1;
}

