public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalCuts = 1 << (n - 1); // number of possible split patterns
    for (int mask = 0; mask < totalCuts; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int last = 0;
        boolean ok = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String part = s.substring(last, i + 1);
                if (!seen.add(part)) { // duplicate found
                    ok = false;
                    break;
                }
                last = i + 1;
            }
        }
        if (!ok) {
            continue;
        }
        // add the final segment
        String part = s.substring(last);
        if (!seen.add(part)) {
            continue;
        }
        if (seen.size() > max) {
            max = seen.size();
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] max = {0};
    java.util.Set<String> used = new java.util.HashSet<>();
    new Object() {
        void dfs(int idx) {
            if (idx == n) {
                if (used.size() > max[0]) max[0] = used.size();
                return;
            }
            for (int end = idx + 1; end <= n; end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(end);
                    used.remove(sub);
                }
            }
        }
    }.dfs(0);
    return max[0];
}

public int maxUniqueSplit(String s) {
    int[] max = {0};
    class DFS {
        void search(int idx, java.util.Set<String> used, int count) {
            if (idx == s.length()) {
                if (count > max[0]) max[0] = count;
                return;
            }
            for (int end = idx + 1; end <= s.length(); end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    search(end, used, count + 1);
                    used.remove(sub);
                }
            }
        }
    }
    new DFS().search(0, new java.util.HashSet<>(), 0);
    return max[0];
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int count = 0;
        StringBuilder curr = new StringBuilder();
        boolean valid = true;
        for (int i = 0; i < n; i++) {
            curr.append(s.charAt(i));
            if (i == n - 1 || ((mask >> i) & 1) == 1) {
                String sub = curr.toString();
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                count++;
                curr.setLength(0);
            }
        }
        if (valid && count > max) {
            max = count;
        }
    }
    return max;
}

