public String getSmallestString(int n, int k) {
    int needed = k - n; // additional value needed beyond all 'a's
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    for (int i = n - 1; i >= 0 && needed > 0; i--) {
        int add = Math.min(25, needed); // can increase a char up to 'z' (value 26)
        sb.setCharAt(i, (char) ('a' + add));
        needed -= add;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remaining = n - i - 1;
        int maxRemaining = remaining * 26;
        int val = Math.max(1, k - maxRemaining);
        sb.append((char) ('a' + val - 1));
        k -= val;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    // Initial string of all 'a's
    char[] chars = new char[n];
    java.util.Arrays.fill(chars, 'a');
    int remaining = k - n; // amount still needed beyond the minimal sum of 'a's

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can increase by at most 25 ('a' -> 'z')
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    int remainingSum = k;
    for (int i = 0; i < n; i++) {
        int positionsLeft = n - i - 1;
        for (int val = 1; val <= 26; val++) {
            int sumAfter = remainingSum - val;
            int minPossible = positionsLeft;          // 1*positionsLeft
            int maxPossible = positionsLeft * 26;     // 26*positionsLeft
            if (sumAfter < minPossible || sumAfter > maxPossible) {
                continue;
            }
            sb.append((char) ('a' + val - 1));
            remainingSum = sumAfter;
            break;
        }
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char)(result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

