public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int common = ones & twos;
        ones ^= common;
        twos ^= common;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >>> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;     // bits that have appeared twice
        ones ^= num;            // bits that have appeared once
        int commonMask = ~(ones & twos); // clear bits that have appeared three times
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update 'twos' with bits that have appeared twice
        twos |= ones & num;
        // Update 'ones' with bits that have appeared once
        ones ^= num;
        // Bits that have appeared three times in both 'ones' and 'twos'
        int common = ones & twos;
        // Remove bits that have appeared three times
        ones &= ~common;
        twos &= ~common;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update twos with bits that appear twice
        twos = twos | (ones & num);
        // Update ones with bits that appear once
        ones = ones ^ num;
        // Bits that have appeared three times are removed from ones and twos
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long)i);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int)current);
        }
        long lastDigit = current % 10;
        if (lastDigit > 0) {
