    if (high < 0) return result;
    java.util.ArrayDeque<Long> queue = new java.util.ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) queue.add((long) i);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur >= low && cur <= high) result.add((int) cur);
        if (cur > high) continue;
        int last = (int) (cur % 10);
        if (last > 0) {
            long next = cur * 10 + (last - 1);
            if (next <= high) queue.add(next);
        }
        if (last < 9) {
            long next = cur * 10 + (last + 1);
            if (next <= high) queue.add(next);
        }
    }
    java.util.Collections.sort(result);
    return result;
}

