public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;
    int m = mat.length, n = mat[0].length;
    int[][][] dp = new int[m][n][4]; // 0: left, 1: up, 2: diag, 3: anti-d
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = 1 + (j > 0 ? dp[i][j - 1][0] : 0);          // horizontal
                dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0);          // vertical
                dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0); // diagonal
                dp[i][j][3] = 1 + (i > 0 && j + 1 < n ? dp[i - 1][j + 1][3] : 0); // anti-diagonal
                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > max) {
                        max = dp[i][j][k];
                    }
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long abs = Math.abs((long) n);
    String s = Long.toString(abs);
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    int first = len % 3;
    if (first == 0) first = 3;
    sb.append(s, 0, first);
    for (int i = first; i < len; i += 3) {
        sb.append('.').append(s, i, i + 3);
    }
    if (negative) sb.insert(0, '-');
    return sb.toString();
}

