public static int squarePermutations(int[] A) {
    int n = A.length;
    Map<Integer, Integer> freq = new HashMap<>();
    for (int num : A) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }

    class Solver {
        int dfs(int prev, int used) {
            if (used == n) {
                return 1;
            }
            int total = 0;
            for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                if (count == 0) continue;
                if (prev != -1 && !isSquare(prev + val)) continue;
                entry.setValue(count - 1);
                total += dfs(val, used + 1);
                entry.setValue(count);
            }
            return total;
        }

        boolean isSquare(int sum) {
            int r = (int) Math.sqrt(sum);
            return r * r == sum;
        }
    }

    Solver solver = new Solver();
    int result = 0;
    for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int val = entry.getKey();
        int count = entry.getValue();
        entry.setValue(count - 1);
        result += solver.dfs(val, 1);
        entry.setValue(count);
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            can[i][j] = root * root == sum;
        }
    }
    int fullMask = (1 << n) - 1;
    Map<Long, Integer> memo = new HashMap<>();
    // Helper function return number of ways from state (prevIndex, mask)
    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        public Integer apply(Integer prev, Integer mask) {
            long key = (((long) prev + 1) << 32) | mask;
            if (mask == fullMask) return 1;
            if (memo.containsKey(key)) return memo.get(key);
            int total = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (prev == -1 || can[prev][next]) {
                    total += apply(next, mask | (1 << next));
                }
            }
            memo.put(key, total);
            return total;
        }
    };
    return dfs.apply(-1, 0);
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    class Back {
        void dfs(int pos, int prev) {
            if (pos == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (pos > 0) {
                    int sum = prev + arr[i];
                    int r = (int) Math.sqrt(sum);
                    if (r * r != sum) continue;
                }
                if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
                used[i] = true;
                dfs(pos + 1, arr[i]);
                used[i] = false;
            }
        }
    }
    new Back().dfs(0, -1);
    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (top >= 0 && heights[stack[top]] > h) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

