    for (int d = 0; d < m + n - 1; d++) {
        int row = d < m ? d : m - 1;
        int col = d - row;
        if (d % 2 == 0) {
            // Traverse up-right
            int r = row, c = col;
            while (r >= 0 && c < n) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Traverse down-left
            int r = row, c = col;
            while (c >= 0 && r < m) {
