public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return new int[0];
    int m = mat.length, n = mat[0].length;
    int[] res = new int[m * n];
    int row = 0, col = 0, dir = 1; // 1 = up-right, -1 = down-left
    for (int i = 0; i < m * n; i++) {
        res[i] = mat[row][col];
        if (dir == 1) {
            if (col == n - 1) { // hit last column
                row++;
                dir = -1;
            } else if (row == 0) { // hit first row
                col++;
                dir = -1;
            } else {
                row--;
                col++;
            }
        } else { // dir == -1
            if (row == m - 1) { // hit last row
                col++;
                dir = 1;
            } else if (col == 0) { // hit first column
                row++;
                dir = 1;
            } else {
                row++;
                col--;
            }
        }
    }
    return res;
}

