            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            // traverse from top to bottom
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[index++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

public static int findSmallestInteger(int n) {
    // Convert the number to a char array of its digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    // If no such index exists, the digits are in descending order (highest permutation)
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of i that is greater than digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 3: Reverse the subarray from i+1 to the end to get the lowest possible number
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char c = digits[left];
        digits[left] = digits[right];
        digits[right] = c;
        left++;
        right--;
    }

    // Convert back to number
    long resultLong = 0;
    for (char c : digits) {
        resultLong = resultLong * 10 + (c - '0');
        if (resultLong > Integer.MAX_VALUE) {
            return -1; // overflow case
        }
    }

    return (int) resultLong;
}

