public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) return result;
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    java.util.List<String> current = new java.util.ArrayList<>();
    if (n % 2 == 0) { // even length
        current.add("");
    } else { // odd length
        current.add("0");
        current.add("1");
        current.add("8");
    }
    // Pair strings: left + right
    String[] pairs = {"00","11","69","88","96"};
    while (current.get(0).length() < n) {
        java.util.List<String> next = new java.util.ArrayList<>();
        int currLen = current.get(0).length();
        for (String s : current) {
            for (String pair : pairs) {
                // Avoid leading zero in the final number
                if (currLen + 2 == n && pair.charAt(0) == '0') continue;
                next.add(pair + s + pair.charAt(1));
            }
        }
        current = next;
    }
    return current;
}

